<template><section class="basic-calculator" aria-label="普通计算器" tabindex="0" @keydown="onKey"><p class="tool-note">按键式日常计算器：连续运算按输入顺序执行，不使用表达式优先级。加减时百分数按前一数值计算（200 + 10% = 220），乘除时 % 表示除以 100。结果约保留 15 位有效数字，采用浮点运算。</p><div class="basic-machine"><div class="basic-context"><span>{{state.memorySet?'M':''}}</span><span>{{pendingText}}</span></div><label class="tool-label">显示<input :value="state.error||state.display" readonly aria-label="普通计算器显示" :aria-invalid="!!state.error" /></label><div class="basic-memory"><button v-for="key in memoryKeys" :key="key" type="button" :title="memoryTitles[key]" @click="press(key)">{{key}}</button></div><div class="basic-keys"><button v-for="key in keys" :key="key" type="button" :class="{'basic-equals':key==='=','basic-operator':['+','−','×','÷'].includes(key)}" :aria-label="key==='⌫'?'普通计算器退格':key==='='?'普通计算器等于':key==='±'?'切换正负号':key" @click="press(key==='⌫'?'Backspace':key)">{{key}}</button></div><div class="tool-actions"><button type="button" :disabled="!!state.error" @click="copy">复制普通计算器结果</button><span>内存：{{memoryValue}}</span></div></div><p class="tool-note">AC 清除当前运算，CE 清除当前输入；MC 清除内存，MR 读取内存，M+ / M− 累加或累减。可聚焦显示框或面板后使用数字、运算键、Enter、Backspace、Delete 和 Esc。</p><p v-if="feedback" role="status">{{feedback}}</p><div v-if="state.history.length" class="basic-history"><header><strong>本次页面记录</strong><button type="button" @click="state.history=[]">清空普通计算记录</button></header><ol><li v-for="(item,index) in state.history" :key="index">{{item}}</li></ol></div></section></template>
<script>
import {basicCalculatorState,basicCalculatorStep,compactNumber} from '../../utils/basic-calculator.mjs';
export default {name:'BasicCalculatorTool',data:()=>({state:basicCalculatorState(),feedback:'',keys:['AC','CE','⌫','÷','7','8','9','×','4','5','6','−','1','2','3','+','±','0','.','='],memoryKeys:['MC','MR','M+','M-','%'],memoryTitles:{MC:'清除内存',MR:'读取内存','M+':'内存加上当前值','M-':'内存减去当前值','%':'百分比'}}),computed:{pendingText(){return this.state.operator?compactNumber(this.state.stored)+' '+({'*':'×','/':'÷','-':'−','+':'+'})[this.state.operator]:'';},memoryValue(){return compactNumber(this.state.memory);}},methods:{press(key){this.state=basicCalculatorStep(this.state,key);this.feedback=this.state.error;},onKey(event){if(event.ctrlKey||event.metaKey||event.altKey)return;if(event.target.tagName==='BUTTON'&&(event.key==='Enter'||event.key===' '))return;const key=event.key==='='||event.key==='Enter'?'=':event.key;if(/^\d$/.test(key)||['+','-','*','/','.','%','=','Backspace','Delete','Escape'].includes(key)){event.preventDefault();this.press(key);}},async copy(){try{await navigator.clipboard.writeText(this.state.display);this.feedback='已复制普通计算器结果';}catch{this.feedback='复制未完成，请选择显示文字手动复制';}}}};
</script>
<style scoped>.basic-machine{max-width:390px;border:1px solid var(--el-border-color);border-radius:14px;padding:16px;background:var(--ui-accent-soft);}.basic-context{display:flex;justify-content:space-between;min-height:20px;color:var(--el-text-color-secondary);}.basic-machine input{font:600 27px/1.5 Consolas,monospace!important;text-align:right;width:100%;}.basic-memory{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin:12px 0;}.basic-keys{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;}.basic-keys button{min-height:48px;font-size:19px!important;}.basic-keys .basic-equals{background:var(--ui-accent)!important;color:var(--el-bg-color)!important;}.basic-keys .basic-operator{font-weight:600;}.basic-history{margin-top:16px;}.basic-history header{display:flex;gap:10px;align-items:center;flex-wrap:wrap;}.basic-history li{font:13px/1.8 Consolas,monospace;overflow-wrap:anywhere;}</style>
